export const MASTER_VIEW_GUIDANCE='Панель master показати строго фронтально, без перспективного спотворення самої панелі, фотографічних тіней, відблисків, об’ємного рельєфу та службових підписів. Сюжет усередині панелі може передавати перспективу й глибину через перекривання, масштаб і чорне гравіювання. Зберегти чіткі межі деталей і функціональні штрихи форми; мінімізувати лише зайву фактуру дерева, а не змістове гравіювання. Штрихована тінь усередині сюжету допустима лише як явно задане чорне гравіювання на відповідній поверхні, без градієнтів морилки й світлих ліній на чорному.';
export const COMPOSITION_GUIDANCE='Спочатку визначити, чи доречна просторова сцена, чи свідомо пласка композиція. Для сцени записати головний акцент, рух погляду, передній/середній/задній плани за потреби, дії й зв’язки об’єктів та конкретні перекривання: що попереду, що позаду, де контур заднього об’єкта зникає й відновлюється. Не розкладати всі мотиви окремими наліпками на однаковій відстані. Підтримати форму й простір цільовими чорними штрихами, контурним гравіюванням або локальною штриховкою; дальній план спростити. Не нав’язувати три плани чи перекривання орнаменту, символу або лаконічному циферблату. Візуальна глибина НЕ означає додаткові фізичні шари: вставки лежать в одній площині, виготовляються лише видимі частини. Перекривання не повинні породжувати крихкі перемички, тонкі кінчики або багато дрібних окремих фрагментів; усі видимі фрагменти рахувати як фізичні частини. Один колір на деталь, лише задана палітра, гравіювання чорне; на чорному не використовувати світле псевдогравіювання.';
export const COMPOSITION_REVIEW_GUIDANCE='Перевір не тільки наявність об’єктів, а фактичні просторові зв’язки: чи читаються ближній і дальній плани, чи є дія/контакт/опора/спільний напрямок, чи задній контур переривається на перекритій ділянці, чи передній елемент справді закриває задній, чи гравіювання допомагає формі, а не є випадковою фактурою. Порівняй із композиційним планом, коли він наданий, і перевір узгодженість master/preview. Окремо оцінити художню глибину та фізичні шари; не вимагати рельєфу або світлого гравіювання. Для свідомо плаского сюжету просторові критерії можуть бути not_applicable з поясненням, без вимоги додати плани. Не приймати набір відокремлених наліпок за цілісну сцену лише через наявність усіх предметів. Для кожної проблеми назвати видиме місце, конкретну дію й мету, наприклад: завести гілку за корпус птаха і прибрати прихований контур. Невиміряну геометрію не позначати перевіреною.';
export const COMPOSITION_CHECK_LABELS={hierarchy:'Головний акцент',depth:'Просторові плани',relationships:'Взаємодія об’єктів',occlusion:'Перекривання й контури',engraving:'Гравіювання форми',manufacturability:'Виготовлення деталей',pair_consistency:'Узгодженість двох видів'};
export function compositionReviewHTML(report,esc){
  if(!Array.isArray(report?.composition_checks)||!report.composition_checks.length)return '';
  const statuses={pass:'Прийнятно',changes_required:'Потрібна правка',not_applicable:'Не застосовується',not_checked:'Не перевірено'};
  return `<details class="composition-review"><summary>Художня перевірка за аспектами</summary>${report.composition_checks.map(check=>`<div class="composition-check"><strong>${esc(COMPOSITION_CHECK_LABELS[check.aspect]||check.aspect)} · ${esc(statuses[check.verdict]||check.verdict)}</strong><p>${esc(check.observation)}</p>${check.suggested_action?`<p>${esc(check.suggested_action)}</p>`:''}</div>`).join('')}</details>`;
}
